head.script:
scwin.screenId = "jldods70209";

///////// 1. 변수 및 선언 영역 /////////

scwin.formCd = "";

scwin.formNm = "";

scwin.formVer = "";

scwin.formText = "";


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_ReportData.get("total")) + "건 [" + String(dma_ReportData.get("currentPage")) + "/" + String(dma_ReportData.get("endListPage")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_goSearchReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


// [A] 초기 목록 미해결 — jldods70209: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70209.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_2_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_2_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_2_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70209.form_2_onsubmit' }); }
};

/**
 * @event
 * @name scwin.ipt_searchWord_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_searchWord_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_searchWord_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.enterSearchForm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70209.ipt_searchWord_onkeyup' }); }
};

/**
 * @event
 * @name scwin.input_14_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_14_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_14_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70209.input_14_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.initPageIndex(); await scwin.goSearch();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70209.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_ReportDataList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_ReportDataList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.goAction === 'function') { scwin.goAction(r["formCd"], r["formKorNm"], r["formVer"], r["formAdmInstTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goAction (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goAction'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goSearch = async function () {
    try { return await $c.data.downFile("/discls/fssFile.do", "", ($c.util.getComponent("dma_goSearchReq") ? $c.util.getComponent("dma_goSearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_ReportDataList_fmt_column2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_ReportDataList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_ReportDataList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "formAdmInstTpCd") ?? '') : '');
        if (v === '1') { return "거래소"; }
        return "금감원";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_ReportDataList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.enterSearchForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.enterSearchForm = async function () {
    /* sdd-asis-lifecycle:begin enterSearchForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.goSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch = async function () {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    blockLoading();
    $c.util.getComponent('dma_goSearchReq').set('method', "searchAllFile");
    (document.frmReportSearch || { elements: [] }).action = "/discls/fssFile.do";
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selectData
 * @author Inswave
 * @date 2026. 09. 29
 * @param fCd fNm fVer fText
 * @returns
 * @hidden N
*/
scwin.selectData = function (fCd, fNm, fVer, fText) {
    /* sdd-asis-lifecycle:begin fn_selectData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.formCd = fCd;
    scwin.formNm = fNm;
    scwin.formVer = fVer;
    scwin.formText = fText;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.select
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.select = function () {
    /* sdd-asis-lifecycle:begin fn_select — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData(scwin.formCd, scwin.formNm, scwin.formVer, scwin.formText) : void 0), $c.win.closePopup([scwin.formCd, scwin.formNm, scwin.formVer, scwin.formText]));
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goAction
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formNm formVer formTpCd
 * @returns
 * @hidden N
*/
scwin.goAction = function (formCd, formNm, formVer, formTpCd) {
    /* sdd-asis-lifecycle:begin goAction — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let formText = "거래소";
    if (formTpCd !== '1') {
        formText = "금감원";
    }
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData(formCd, formNm, formVer, formText) : void 0), $c.win.closePopup([formCd, formNm, formVer, formText]));
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_49_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_49_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_49.page' }); } scwin.goSearch(); };
